import '../../../core/constants/app_constants.dart';
import 'institution.dart';
import '../../../core/utils/formatters.dart';

/// A course a student can apply to. Mirrors `public.programs`.
class Program {
  final String id;
  final String institutionId;
  final String name;
  final String level;
  final String fieldOfStudy;

  final double? tuitionMin;
  final double? tuitionMax;
  final String tuitionCurrency;
  final int? durationMonths;
  final List<String> intakes;

  final double? minGradeValue;
  final String? minGradeScheme;
  final double? minEnglishBand;

  /// Generated by the database: `min_grade_value` mapped onto 0-100 so it is
  /// comparable with a passport's `normalizedGrade` across grading systems.
  final double? normalizedMinGrade;

  final bool scholarshipAvailable;
  final Map<String, dynamic> requirements;
  final bool isActive;

  /// Present when the query joined institutions.
  final Institution? institution;

  const Program({
    required this.id,
    required this.institutionId,
    required this.name,
    required this.level,
    required this.fieldOfStudy,
    this.tuitionMin,
    this.tuitionMax,
    this.tuitionCurrency = 'USD',
    this.durationMonths,
    this.intakes = const [],
    this.minGradeValue,
    this.minGradeScheme,
    this.minEnglishBand,
    this.normalizedMinGrade,
    this.scholarshipAvailable = false,
    this.requirements = const {},
    this.isActive = true,
    this.institution,
  });

  String get levelLabel => AppConstants.studyLevels[level] ?? level;

  String get tuitionDisplay {
    if (tuitionMin == null) return 'Tuition not published';
    final min = formatThousands(tuitionMin!.round());
    if (tuitionMax == null || tuitionMax == tuitionMin) {
      return '$tuitionCurrency $min / year';
    }
    return '$tuitionCurrency $min–${formatThousands(tuitionMax!.round())} / year';
  }

  String get durationDisplay {
    final months = durationMonths;
    if (months == null) return '—';
    if (months % 12 == 0) {
      final years = months ~/ 12;
      return years == 1 ? '1 year' : '$years years';
    }
    return '$months months';
  }

  /// Entry requirement in the scheme the institution published it in. Shown
  /// as-is rather than converted, because a student recognises their own
  /// system and a converted number invites arguments we cannot win.
  String get entryRequirementDisplay {
    if (minGradeValue == null) return 'No published minimum';
    switch (minGradeScheme) {
      case 'percentage':
        return '${_trim(minGradeValue!)}% minimum';
      case 'gpa_4':
        return '${_trim(minGradeValue!)} / 4.0 GPA minimum';
      case 'gpa_5':
        return '${_trim(minGradeValue!)} / 5.0 GPA minimum';
      case 'ib':
        return '${_trim(minGradeValue!)} / 45 IB minimum';
      default:
        return '${_trim(minGradeValue!)} minimum';
    }
  }

  String get englishRequirementDisplay => minEnglishBand == null
      ? 'No published English requirement'
      : 'IELTS ${_trim(minEnglishBand!)} or equivalent';

  static String _trim(double v) =>
      v == v.roundToDouble() ? v.toStringAsFixed(0) : v.toStringAsFixed(1);


  factory Program.fromMap(Map<String, dynamic> map) {
    final nested = map['institutions'] as Map<String, dynamic>?;
    return Program(
      id: map['id'] as String,
      institutionId: map['institution_id'] as String,
      name: map['name'] as String,
      level: map['level'] as String,
      fieldOfStudy: map['field_of_study'] as String,
      tuitionMin: _toDouble(map['tuition_min']),
      tuitionMax: _toDouble(map['tuition_max']),
      tuitionCurrency: map['tuition_currency'] as String? ?? 'USD',
      durationMonths: (map['duration_months'] as num?)?.toInt(),
      intakes: map['intakes'] == null
          ? const []
          : (map['intakes'] as List).map((e) => e.toString()).toList(),
      minGradeValue: _toDouble(map['min_grade_value']),
      minGradeScheme: map['min_grade_scheme'] as String?,
      minEnglishBand: _toDouble(map['min_english_band']),
      normalizedMinGrade: _toDouble(map['normalized_min_grade']),
      scholarshipAvailable: map['scholarship_available'] as bool? ?? false,
      requirements: (map['requirements'] as Map?)?.cast<String, dynamic>() ?? const {},
      isActive: map['is_active'] as bool? ?? true,
      institution: nested == null ? null : Institution.fromMap(nested),
    );
  }

  static double? _toDouble(dynamic v) => v == null ? null : (v as num).toDouble();
}
